def predict_halo(a):
    n,m=a.shape; y=a.copy();
    # convert all outer-border 8s
    for r in range(n):
        for c in range(m):
            if r==0 or r==n-1 or c==0 or c==m-1:
                if y[r,c]==8: y[r,c]=7
    # select 1 components 4-connected touching boundary; halo 8-neighbor only for them
    seen=np.zeros(a.shape,bool); from collections import deque
    for r,c in np.ndindex(a.shape):
        if a[r,c]==1 and not seen[r,c]:
            q=deque([(r,c)]); seen[r,c]=True; comp=[]
            while q:
                x,z=q.popleft(); comp.append((x,z))
                for dx,dz in [(1,0),(-1,0),(0,1),(0,-1)]:
                    xx,zz=x+dx,z+dz
                    if 0<=xx<n and 0<=zz<m and a[xx,zz]==1 and not seen[xx,zz]: seen[xx,zz]=1;q.append((xx,zz))
            if any(x in [0,n-1] or z in [0,m-1] for x,z in comp):
                for x,z in comp:
                    for dx in [-1,0,1]:
                        for dz in [-1,0,1]:
                            xx,zz=x+dx,z+dz
                            if 0<=xx<n and 0<=zz<m and a[xx,zz]==8:y[xx,zz]=7
    return y
